insert into products (id, name, description, price_minor, currency, images, category_id, featured, created_at) values
  ('hass-avocados', 'Hass Avocados', 'Creamy, ready-to-ripen avocados picked at peak season. Perfect for toast, salads, and guacamole.', 449, 'USD', '["https://images.unsplash.com/photo-1523049673857-eb18f1d7b578?w=900&q=80","https://images.unsplash.com/photo-1601039641847-7857b994d704?w=900&q=80"]'::jsonb, 'produce', true, '2026-07-02T10:00:00.000Z'),
  ('organic-strawberries', 'Organic Strawberries', 'Sweet, fragrant strawberries grown without synthetic pesticides. Picked and packed within a day.', 599, 'USD', '["https://images.unsplash.com/photo-1464965911861-746a04b4bca6?w=900&q=80","https://images.unsplash.com/photo-1518635017498-87f514b751ba?w=900&q=80"]'::jsonb, 'produce', false, '2026-07-10T10:00:00.000Z'),
  ('heirloom-tomatoes', 'Heirloom Tomatoes', 'A colorful mix of heritage varieties with real depth of flavor. Best kept out of the fridge.', 379, 'USD', '["https://images.unsplash.com/photo-1546094096-0df4bcaaa337?w=900&q=80","https://images.unsplash.com/photo-1592841200221-a6898f307baa?w=900&q=80"]'::jsonb, 'produce', false, '2026-06-18T10:00:00.000Z'),
  ('baby-spinach', 'Baby Spinach', 'Tender young spinach leaves, triple washed and ready for salads or a quick wilt.', 299, 'USD', '["https://images.unsplash.com/photo-1576045057995-568f588f82fb?w=900&q=80","https://images.unsplash.com/photo-1540420773420-3366772f4999?w=900&q=80"]'::jsonb, 'produce', false, '2026-06-30T10:00:00.000Z'),
  ('country-sourdough', 'Country Sourdough', 'Naturally leavened for 24 hours with a deep crust and an open, tangy crumb. Baked every morning.', 649, 'USD', '["https://images.unsplash.com/photo-1509440159596-0249088772ff?w=900&q=80","https://images.unsplash.com/photo-1608198093002-ad4e005484ec?w=900&q=80"]'::jsonb, 'bakery', true, '2026-06-25T10:00:00.000Z'),
  ('butter-croissants', 'Butter Croissants', 'Laminated with French butter for 27 flaky layers. Warm them for five minutes and thank us later.', 459, 'USD', '["https://images.unsplash.com/photo-1555507036-ab1f4038808a?w=900&q=80","https://images.unsplash.com/photo-1530610476181-d83430b64dcd?w=900&q=80"]'::jsonb, 'bakery', false, '2026-07-08T10:00:00.000Z'),
  ('blueberry-muffins', 'Blueberry Muffins', 'Bursting with wild blueberries under a crunchy sugar top. Baked in small batches.', 549, 'USD', '["https://images.unsplash.com/photo-1607958996333-41aef7caefaa?w=900&q=80","https://images.unsplash.com/photo-1558961363-fa8fdf82db35?w=900&q=80"]'::jsonb, 'bakery', false, '2026-05-28T10:00:00.000Z'),
  ('rustic-baguette', 'Rustic Baguette', 'A crisp, golden baguette with a light, airy interior. Best eaten the day it is baked.', 349, 'USD', '["https://images.unsplash.com/photo-1549931319-a545dcf3bc73?w=900&q=80","https://images.unsplash.com/photo-1512621776951-a57141f2eefd?w=900&q=80"]'::jsonb, 'bakery', false, '2026-06-12T10:00:00.000Z'),
  ('organic-whole-milk', 'Organic Whole Milk', 'Fresh whole milk from grass-fed herds, gently pasteurized and nothing else.', 389, 'USD', '["https://images.unsplash.com/photo-1550583724-b2692b85b150?w=900&q=80","https://images.unsplash.com/photo-1563636619-e9143da7973b?w=900&q=80"]'::jsonb, 'dairy-eggs', false, '2026-07-05T10:00:00.000Z'),
  ('free-range-eggs', 'Free-Range Eggs', 'Large eggs from hens that actually go outside. Rich yolks made for weekend breakfasts.', 549, 'USD', '["https://images.unsplash.com/photo-1582722872445-44dc5f7e3c8f?w=900&q=80","https://images.unsplash.com/photo-1506976785307-8732e854ad03?w=900&q=80"]'::jsonb, 'dairy-eggs', true, '2026-06-20T10:00:00.000Z'),
  ('aged-cheddar', 'Aged Cheddar', 'Twelve months of patience in every block: sharp, crumbly, and a little crystalline.', 799, 'USD', '["https://images.unsplash.com/photo-1486297678162-eb2a19b0a32d?w=900&q=80","https://images.unsplash.com/photo-1452195100486-9cc805987862?w=900&q=80"]'::jsonb, 'dairy-eggs', false, '2026-04-15T10:00:00.000Z'),
  ('greek-yogurt', 'Greek Yogurt', 'Thick, strained yogurt with live cultures. A blank canvas for honey, fruit, or granola.', 449, 'USD', '["https://images.unsplash.com/photo-1488477181946-6428a0291777?w=900&q=80","https://images.unsplash.com/photo-1498837167922-ddd27525d352?w=900&q=80"]'::jsonb, 'dairy-eggs', false, '2026-05-22T10:00:00.000Z'),
  ('italian-spaghetti', 'Italian Spaghetti', 'Bronze-die pasta from Puglia with the rough texture sauce clings to. Cooks in nine minutes.', 329, 'USD', '["https://images.unsplash.com/photo-1621996346565-e3dbc646d9a9?w=900&q=80","https://images.unsplash.com/photo-1551462147-37885acc36f1?w=900&q=80"]'::jsonb, 'pantry', false, '2026-05-10T10:00:00.000Z'),
  ('extra-virgin-olive-oil', 'Extra Virgin Olive Oil', 'Cold-pressed single-estate oil, grassy and peppery. For finishing, dipping, and everything else.', 1299, 'USD', '["https://images.unsplash.com/photo-1474979266404-7eaacbcd87c5?w=900&q=80","https://images.unsplash.com/photo-1596040033229-a9821ebd058d?w=900&q=80"]'::jsonb, 'pantry', true, '2026-06-08T10:00:00.000Z'),
  ('arborio-rice', 'Arborio Rice', 'Plump short-grain rice that releases its starch slowly. The only rice your risotto wants.', 549, 'USD', '["https://images.unsplash.com/photo-1586201375761-83865001e31c?w=900&q=80","https://images.unsplash.com/photo-1536304993881-ff6e9eefa2a6?w=900&q=80"]'::jsonb, 'pantry', false, '2026-03-25T10:00:00.000Z'),
  ('wildflower-honey', 'Wildflower Honey', 'Raw, unfiltered honey from hives that move with the bloom. Floral, golden, never heated.', 899, 'USD', '["https://images.unsplash.com/photo-1587049352846-4a222e784d38?w=900&q=80","https://images.unsplash.com/photo-1558642452-9d2a7deb7f62?w=900&q=80"]'::jsonb, 'pantry', false, '2026-04-30T10:00:00.000Z'),
  ('single-origin-coffee', 'Single-Origin Coffee', 'Ethiopian beans roasted to order with notes of bergamot and stone fruit. Whole bean.', 1449, 'USD', '["https://images.unsplash.com/photo-1495474472287-4d71bcdd2085?w=900&q=80","https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=900&q=80"]'::jsonb, 'beverages', true, '2026-06-28T10:00:00.000Z'),
  ('fresh-orange-juice', 'Fresh Orange Juice', 'Cold-pressed from Valencia oranges the same day it ships. Never from concentrate.', 549, 'USD', '["https://images.unsplash.com/photo-1600271886742-f049cd451bba?w=900&q=80","https://images.unsplash.com/photo-1613478223719-2ab802602423?w=900&q=80"]'::jsonb, 'beverages', false, '2026-07-12T10:00:00.000Z'),
  ('sparkling-water', 'Sparkling Mineral Water', 'Naturally carbonated spring water with fine, persistent bubbles.', 199, 'USD', '["https://images.unsplash.com/photo-1523362628745-0c100150b504?w=900&q=80","https://images.unsplash.com/photo-1616118132534-381148898bb4?w=900&q=80"]'::jsonb, 'beverages', false, '2026-05-15T10:00:00.000Z'),
  ('jasmine-green-tea', 'Jasmine Green Tea', 'Green tea scented with fresh jasmine blossoms over five nights. Twenty biodegradable bags.', 699, 'USD', '["https://images.unsplash.com/photo-1564890369478-c89ca6d9cde9?w=900&q=80","https://images.unsplash.com/photo-1597318181409-cf64d0b5d8a2?w=900&q=80"]'::jsonb, 'beverages', false, '2026-04-08T10:00:00.000Z'),
  ('dark-chocolate-bar', 'Dark Chocolate 70%', 'Small-batch chocolate from Ecuadorian cacao. Intense, fruity, and just bitter enough.', 449, 'USD', '["https://images.unsplash.com/photo-1606312619070-d48b4c652a52?w=900&q=80","https://images.unsplash.com/photo-1511381939415-e44015466834?w=900&q=80"]'::jsonb, 'snacks', true, '2026-06-15T10:00:00.000Z'),
  ('roasted-almonds', 'Sea Salt Roasted Almonds', 'California almonds slow-roasted and finished with flaky sea salt. Dangerously snackable.', 799, 'USD', '["https://images.unsplash.com/photo-1508061253366-f7da158b6d46?w=900&q=80","https://images.unsplash.com/photo-1608797178974-15b35a64ede9?w=900&q=80"]'::jsonb, 'snacks', false, '2026-05-05T10:00:00.000Z'),
  ('sea-salt-crisps', 'Sea Salt Crisps', 'Kettle-cooked potato crisps with skin on and nothing artificial. Loud in the best way.', 349, 'USD', '["https://images.unsplash.com/photo-1566478989037-eec170784d0b?w=900&q=80","https://images.unsplash.com/photo-1613919113640-25732ec5e61f?w=900&q=80"]'::jsonb, 'snacks', false, '2026-06-22T10:00:00.000Z'),
  ('honey-granola', 'Honey Almond Granola', 'Oven-baked clusters of oats, almonds, and honey. Breakfast or straight from the bag.', 599, 'USD', '["https://images.unsplash.com/photo-1517093602195-b40af9688b46?w=900&q=80","https://images.unsplash.com/photo-1571748982800-fa51082c2224?w=900&q=80"]'::jsonb, 'snacks', false, '2026-03-18T10:00:00.000Z');
